<?php
namespace App\Application\Claims;
use App\Application\Audit\AuditWriter;use App\Application\Events\OutboxWriter;use App\Models\{Claim,Document,User};use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Illuminate\Validation\ValidationException;
final class ClaimEvidenceService{public function __construct(private AuditWriter$audit,private OutboxWriter$outbox){}public function attach(Claim$c,Document$d,string$type,string$purpose,User$actor):array{return DB::transaction(function()use($c,$d,$type,$purpose,$actor){$c=Claim::whereKey($c->id)->lockForUpdate()->firstOrFail();if($c->tenant_id!==app(\App\Domain\Tenancy\TenantContext::class)->id()||$d->tenant_id!==$c->tenant_id)abort(404);if(!$d->sha256||$d->scan_status!=='CLEAN')throw ValidationException::withMessages(['document_id'=>__('wave7.evidence_not_clean')]);if(DB::table('claim_documents')->where(['claim_id'=>$c->id,'document_id'=>$d->id])->exists())throw ValidationException::withMessages(['document_id'=>__('wave7.evidence_exists')]);$id=(string)Str::uuid();DB::table('claim_documents')->insert(['id'=>$id,'claim_id'=>$c->id,'document_id'=>$d->id,'evidence_type'=>$type,'evidence_hash'=>$d->sha256,'status'=>'SUBMITTED','submitted_by'=>$actor->id,'submitted_at'=>now()]);$this->custody($c,$d,'RECEIVED',null,$actor,$purpose);$this->audit->record('claim.evidence.attached','claim',$c->id,['document_id'=>$d->id,'sha256'=>$d->sha256]);$this->outbox->record('claim.evidence.attached','claim',$c->id,['document_id'=>$d->id]);return['id'=>$id,'status'=>'SUBMITTED'];});}public function verify(Claim$c,Document$d,bool$accepted,string$purpose,User$actor):void{DB::transaction(function()use($c,$d,$accepted,$purpose,$actor){$link=DB::table('claim_documents')->where(['claim_id'=>$c->id,'document_id'=>$d->id])->lockForUpdate()->first();if(!$link||$c->tenant_id!==app(\App\Domain\Tenancy\TenantContext::class)->id())abort(404);if(!hash_equals((string)$link->evidence_hash,(string)$d->sha256))throw ValidationException::withMessages(['document_id'=>__('wave7.evidence_hash_changed')]);DB::table('claim_documents')->where(['claim_id'=>$c->id,'document_id'=>$d->id])->update(['status'=>$accepted?'VERIFIED':'REJECTED','verified_by'=>$actor->id,'verified_at'=>now(),'rejection_reason'=>$accepted?null:$purpose]);$this->custody($c,$d,$accepted?'VERIFIED':'REJECTED',$link->submitted_by,$actor,$purpose);$this->audit->record('claim.evidence.'.($accepted?'verified':'rejected'),'claim',$c->id,['document_id'=>$d->id]);});}private function custody(Claim$c,Document$d,string$event,?string$from,User$to,string$purpose):void{DB::table('claim_evidence_custody_events')->insert(['id'=>(string)Str::uuid(),'claim_id'=>$c->id,'document_id'=>$d->id,'event_type'=>$event,'from_actor_id'=>$from,'to_actor_id'=>$to->id,'content_hash'=>$d->sha256,'purpose'=>$purpose,'metadata'=>'{}','occurred_at'=>now()]);}}
